# Workspace Management Components

Based on the latest workspace API changes, I'll create the components needed for users to manage workspace lifecycle (start, restart, stop, delete).

## 1. Workspace List Component

```vue src/components/workspaces/WorkspaceList.vue
<script setup>
import { API } from '../../api/api'
import WorkspaceCard from './WorkspaceCard.vue'
</script>

<template>
  <div class="w-full h-full flex flex-col">
    <!-- Header -->
    <div class="navbar bg-base-200 border-b border-base-300 min-h-0 px-4 py-2">
      <div class="flex-1">
        <div class="flex items-center gap-2">
          <i class="fa-solid fa-cubes text-primary text-lg"></i>
          <h1 class="font-bold text-lg">Workspaces</h1>
          <span class="badge badge-primary">{{ workspaces.length }}</span>
        </div>
      </div>
      <button class="btn btn-primary btn-sm" @click="showCreateModal = true" v-if="isAdmin">
        <i class="fa-solid fa-plus"></i> New Workspace
      </button>
    </div>

    <!-- Content -->
    <div class="flex-1 overflow-y-auto p-4">
      <div v-if="loading" class="flex items-center justify-center h-full">
        <span class="loading loading-spinner loading-lg text-primary"></span>
      </div>

      <div v-else-if="!workspaces.length" class="flex flex-col items-center justify-center h-full text-base-content/50">
        <i class="fa-solid fa-cubes text-4xl mb-3"></i>
        <p class="text-sm">No workspaces available</p>
      </div>

      <div v-else class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        <WorkspaceCard
          v-for="workspace in workspaces"
          :key="workspace.id"
          :workspace="workspace"
          :is-admin="isAdmin"
          @edit="editWorkspace"
          @delete="deleteWorkspace"
          @action="handleWorkspaceAction"
          @files="openFileManager"
        />
      </div>
    </div>

    <!-- Create Modal -->
    <div v-if="showCreateModal" class="modal modal-open">
      <div class="modal-box w-full max-w-md">
        <h3 class="font-bold text-lg mb-4">Create New Workspace</h3>

        <div class="form-control gap-4">
          <div>
            <label class="label"><span class="label-text">Workspace Name *</span></label>
            <input
              v-model="newWorkspace.name"
              type="text"
              class="input input-bordered w-full"
              placeholder="e.g., My Dev Workspace"
            />
          </div>

          <div>
            <label class="label"><span class="label-text">Description</span></label>
            <textarea
              v-model="newWorkspace.description"
              class="textarea textarea-bordered w-full"
              placeholder="Optional description..."
              rows="2"
            ></textarea>
          </div>

          <div>
            <label class="label"><span class="label-text">Folder Path *</span></label>
            <input
              v-model="newWorkspace.folder_path"
              type="text"
              class="input input-bordered w-full text-xs"
              placeholder="e.g., my-workspace"
            />
            <label class="label"><span class="label-text-alt text-base-content/50">Used for file storage</span></label>
          </div>

          <div>
            <label class="label"><span class="label-text">Projects</span></label>
            <select v-model="selectedProjectIds" class="select select-bordered w-full" multiple size="3">
              <option value="*" selected>★ All Projects</option>
              <option v-for="p in availableProjects" :key="p.project_id" :value="p.project_id">
                {{ p.project_name }}
              </option>
            </select>
          </div>
        </div>

        <div class="modal-action mt-6">
          <button class="btn btn-ghost" @click="showCreateModal = false">Cancel</button>
          <button class="btn btn-primary" @click="createWorkspace" :disabled="creatingWorkspace">
            <span v-if="creatingWorkspace" class="loading loading-spinner loading-sm"></span>
            Create
          </button>
        </div>
      </div>
      <div class="modal-backdrop" @click="showCreateModal = false"></div>
    </div>
  </div>
</template>

<script>
export default {
  props: [],
  data() {
    return {
      workspaces: [],
      availableProjects: [],
      loading: true,
      showCreateModal: false,
      creatingWorkspace: false,
      selectedProjectIds: ['*'],
      newWorkspace: {
        name: '',
        description: '',
        folder_path: ''
      }
    }
  },
  computed: {
    isAdmin() {
      return this.$storex.user?.role === 'admin'
    }
  },
  async mounted() {
    await this.loadWorkspaces()
    await this.loadProjects()
  },
  methods: {
    async loadWorkspaces() {
      try {
        this.loading = true
        const endpoint = this.isAdmin ? '/workspaces' : '/workspaces/accessible'
        this.workspaces = await API.get(`/api${endpoint}`)
      } catch (error) {
        console.error('Failed to load workspaces:', error)
        this.$storex.notificationQueue.push({
          type: 'error',
          title: 'Failed to load workspaces',
          message: error.message
        })
      } finally {
        this.loading = false
      }
    },

    async loadProjects() {
      try {
        const response = await API.get('/api/projects')
        this.availableProjects = response.projects || []
      } catch (error) {
        console.error('Failed to load projects:', error)
      }
    },

    async createWorkspace() {
      if (!this.newWorkspace.name?.trim() || !this.newWorkspace.folder_path?.trim()) {
        this.$storex.notificationQueue.push({
          type: 'warning',
          title: 'Missing fields',
          message: 'Name and folder path are required'
        })
        return
      }

      try {
        this.creatingWorkspace = true
        await API.post('/api/workspaces', {
          name: this.newWorkspace.name,
          description: this.newWorkspace.description,
          folder_path: this.newWorkspace.folder_path,
          project_ids: this.selectedProjectIds,
          apps: []
        })

        this.$storex.notificationQueue.push({
          type: 'success',
          title: 'Workspace created',
          message: `${this.newWorkspace.name} created successfully`
        })

        this.showCreateModal = false
        this.resetForm()
        await this.loadWorkspaces()
      } catch (error) {
        this.$storex.notificationQueue.push({
          type: 'error',
          title: 'Failed to create workspace',
          message: error.message
        })
      } finally {
        this.creatingWorkspace = false
      }
    },

    async editWorkspace(workspace) {
      this.$emit('edit', workspace)
    },

    async deleteWorkspace(workspaceId) {
      if (!confirm('Are you sure? This will delete the workspace and all its files.')) return

      try {
        await API.delete(`/api/workspaces/${workspaceId}`)
        this.$storex.notificationQueue.push({
          type: 'success',
          title: 'Workspace deleted',
          message: 'Workspace removed successfully'
        })
        await this.loadWorkspaces()
      } catch (error) {
        this.$storex.notificationQueue.push({
          type: 'error',
          title: 'Failed to delete workspace',
          message: error.message
        })
      }
    },

    async handleWorkspaceAction(payload) {
      const { workspaceId, action } = payload
      try {
        await API.post(`/api/workspaces/${workspaceId}/${action}`, {})
        this.$storex.notificationQueue.push({
          type: 'success',
          title: `Workspace ${action}ed`,
          message: `Workspace ${action} action completed`
        })
        await this.loadWorkspaces()
      } catch (error) {
        this.$storex.notificationQueue.push({
          type: 'error',
          title: `Failed to ${action} workspace`,
          message: error.message
        })
      }
    },

    openFileManager(workspace) {
      this.$emit('manage-files', workspace)
    },

    resetForm() {
      this.newWorkspace = { name: '', description: '', folder_path: '' }
      this.selectedProjectIds = ['*']
    }
  }
}
</script>
```

