          <div v-for="app in workspace.apps" :key="app.id" class="flex items-center gap-1 px-2 py-1 rounded-lg bg-base-200 text-xs">
            <AppIcon :app="app" />
            <span>{{ app.name }}</span>
          </div>
        </div>
      </div>

      <!-- Divider -->
      <div class="divider my-2"></div>

      <!-- Status & Info -->
      <div class="grid grid-cols-2 gap-2 mb-3 text-xs">
        <div class="flex items-center gap-2">
          <i class="fa-solid fa-folder text-warning"></i>
          <span>{{ workspace.project_ids?.length || 0 }} projects</span>
        </div>
        <div class="flex items-center gap-2">
          <i class="fa-solid fa-users text-info"></i>
          <span>{{ workspace.user_ids?.length ? 'Restricted' : 'Public' }}</span>
        </div>
      </div>

      <!-- Action Buttons -->
      <div class="flex gap-2">
        <button
          class="btn btn-primary btn-sm flex-1"
          @click="$emit('action', { workspaceId: workspace.id, action: 'start' })"
        >
          <i class="fa-solid fa-play text-xs"></i> Start
        </button>
        <button
          class="btn btn-warning btn-sm flex-1"
          @click="$emit('action', { workspaceId: workspace.id, action: 'restart' })"
        >
          <i class="fa-solid fa-rotate-right text-xs"></i> Restart
        </button>
        <button
          class="btn btn-error btn-sm flex-1"
          @click="$emit('action', { workspaceId: workspace.id, action: 'stop' })"
        >
          <i class="fa-solid fa-stop text-xs"></i> Stop
        </button>
      </div>

      <!-- Updated At -->
      <p class="text-xs text-base-content/40 text-right mt-2">{{ formatDate(workspace.updated_at) }}</p>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    workspace: {
      type: Object,
      required: true
    },
    isAdmin: {
      type: Boolean,
      default: false
    }
  },
  methods: {
    formatDate(isoString) {
      if (!isoString) return 'Unknown'
      const date = new Date(isoString)
      return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: '2-digit' })
    }
  }
}
</script>
```

## 3. Workspace File Manager Component

```vue src/components/workspaces/WorkspaceFileManager.vue
<script setup>
import { API } from '../../api/api'
</script>

<template>
  <div class="w-full h-full flex flex-col bg-base-100">
    <!-- Header -->
    <div class="navbar bg-base-200 border-b border-base-300 min-h-0 px-4 py-2">
      <div class="flex-1 flex items-center gap-3">
        <button class="btn btn-ghost btn-sm" @click="$emit('close')">
          <i class="fa-solid fa-arrow-left"></i>
        </button>
        <h2 class="font-bold">{{ workspace.name }} - Files</h2>
      </div>
      <button class="btn btn-primary btn-sm" @click="addFile">
        <i class="fa-solid fa-plus"></i> New File
      </button>
    </div>

    <!-- Content -->
    <div class="flex-1 overflow-hidden flex">
      <!-- File List -->
      <div class="w-64 border-r border-base-300 overflow-y-auto">
        <div v-if="loadingFiles" class="flex items-center justify-center h-full">
          <span class="loading loading-spinner loading-sm"></span>
        </div>

        <div v-else-if="!files.length" class="p-4 text-center text-base-content/50 text-sm">
          <i class="fa-solid fa-folder-open text-2xl mb-2 block"></i>
          <p>No files</p>
        </div>

        <div v-else class="p-2">
          <div
            v-for="file in files"
            :key="file.filename"
            @click="selectFile(file)"
            class="p-3 rounded-lg cursor-pointer transition-colors"
            :class="selectedFile?.filename === file.filename ? 'bg-primary text-primary-content' : 'hover:bg-base-200'"
          >
            <div class="flex items-center gap-2">
              <i :class="getFileIcon(file.filename)"></i>
              <div class="flex-1 min-w-0">
                <p class="font-medium text-sm truncate">{{ file.filename }}</p>
                <p class="text-xs opacity-75">{{ formatSize(file.size) }}</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <!-- File Editor -->
      <div class="flex-1 flex flex-col">
        <div v-if="!selectedFile" class="flex items-center justify-center h-full text-base-content/50">
          <div class="text-center">
            <i class="fa-solid fa-file-lines text-4xl mb-3 block"></i>
            <p>Select a file to edit</p>
          </div>
        </div>

        <div v-else class="flex flex-col h-full">
          <!-- File Header -->
          <div class="border-b border-base-300 px-4 py-3 flex items-center justify-between">
            <div>
              <p class="font-semibold">{{ selectedFile.filename }}</p>
              <p class="text-xs text-base-content/50">{{ formatSize(selectedFile.size) }}</p>
            </div>
            <div class="flex gap-2">
              <button class="btn btn-ghost btn-sm" @click="deleteFile(selectedFile.filename)">
                <i class="fa-solid fa-trash text-error"></i>
              </button>
            </div>
          </div>

          <!-- Editor -->
          <div class="flex-1 p-4 overflow-auto">
            <textarea
              v-model="fileContent"
              class="w-full h-full p-3 font-mono text-sm rounded-lg border border-base-300 focus:outline-none focus:border-primary"
              :style="{ fontFamily: 'monospace' }"
              placeholder="File content..."
            ></textarea>
          </div>

          <!-- Footer -->
          <div class="border-t border-base-300 px-4 py-3 flex gap-2 justify-end">
            <button class="btn btn-ghost btn-sm" @click="cancelEdit">Cancel</button>
            <button class="btn btn-primary btn-sm" @click="saveFile" :disabled="savingFile">
              <span v-if="savingFile" class="loading loading-spinner loading-sm"></span>
              Save
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    workspace: {
      type: Object,
      required: true
    }
  },
  data() {
    return {
      files: [],
      selectedFile: null,
      fileContent: '',
      loadingFiles: false,
      savingFile: false,
      originalContent: ''
    }
  },
  async mounted() {
    await this.loadFiles()
  },
  methods: {
    async loadFiles() {
      try {
        this.loadingFiles = true
        this.files = await API.get(`/api/workspaces/${this.workspace.id}/files`)
        this.selectedFile = null
        this.fileContent = ''
      } catch (error) {
        console.error('Failed to load files:', error)
        this.$storex.notificationQueue.push({
          type: 'error',
          title: 'Failed to load files',
          message: error.message
        })
      } finally {
        this.loadingFiles = false
      }
    },

    async selectFile(file) {
      try {
        this.selectedFile = file
        const response = await API.get(`/api/workspaces/${this.workspace.id}/files/${file.filename}`)
        this.fileContent = response.content
        this.originalContent = response.content
      } catch (error) {
        this.$storex.notificationQueue.push({
          type: 'error',
          title: 'Failed to load file',
          message: error.message
        })
      }
    },

    async saveFile() {
      if (!this.selectedFile) return

      try {
        this.savingFile = true
        await API.put(`/api/workspaces/${this.workspace.id}/files/${this.selectedFile.filename}`, {
          filename: this.selectedFile.filename,
          content: this.fileContent
        })

        this.originalContent = this.fileContent
        this.$storex.notificationQueue.push({
          type: 'success',
          title: 'File saved',
          message: `${this.selectedFile.filename} saved successfully`
        })
      } catch (error) {
        this.$storex.notificationQueue.push({
          type: 'error',
          title: 'Failed to save file',
          message: error.message
        })
      } finally {
        this.savingFile = false
      }
    },

    async deleteFile(filename) {
      if (!confirm(`Delete ${filename}?`)) return

      try {
        await API.delete(`/api/workspaces/${this.workspace.id}/files/${filename}`)
        this.$storex.notificationQueue.push({
          type: 'success',
          title: 'File deleted',
          message: `${filename} deleted successfully`
        })
        await this.loadFiles()
      } catch (error) {
        this.$storex.notificationQueue.push({
          type: 'error',
          title: 'Failed to delete file',
          message: error.message
        })
      }
    },

    async addFile() {
      const filename = prompt('Enter filename:')
      if (!filename) return

      try {
        await API.put(`/api/workspaces/${this.workspace.id}/files/${filename}`, {
          filename: filename,
          content: ''
        })

        this.$storex.notificationQueue.push({
          type: 'success',
          title: 'File created',
          message: `${filename} created successfully`
        })
        await this.loadFiles()
      } catch (error) {
        this.$storex.notificationQueue.push({
          type: 'error',
          title: 'Failed to create file',
          message: error.message
        })
      }
    },

    cancelEdit() {
      this.fileContent = this.originalContent
    },

    getFileIcon(filename) {
      if (filename.includes('Dockerfile')) return 'fa-solid fa-cube text-info'
      if (filename.includes('docker-compose')) return 'fa-solid fa-cubes text-warning'
      if (filename.endsWith('.env')) return 'fa-solid fa-sliders text-success'
      if (filename.endsWith('.sh')) return 'fa-solid fa-terminal text-primary'
      return 'fa-solid fa-file text-base-content/50'
    },

    formatSize(bytes) {
      if (!bytes) return '0 B'
      const k = 1024
      const sizes = ['B', 'KB', 'MB']
      const i = Math.floor(Math.log(bytes) / Math.log(k))
      return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i]
    }
  }
}
</script>
```

## 4. API Methods to Add

```js src/api/api.js
// Add to the API object before the final export

workspaces: {
  async list() {
    return await API.get('/api/workspaces')
  },
  async listAccessible() {
    return await API.get('/api/workspaces/accessible')
  },
  async create(data) {
    return await API.post('/api/workspaces', data)
  },
  async update(workspaceId, data) {
    return await API.put(`/api/workspaces/${workspaceId}`, data)
  },
  async delete(workspaceId) {
    return await API.delete(`/api/workspaces/${workspaceId}`)
  },
  async start(workspaceId) {
    return await API.post(`/api/workspaces/${workspaceId}/start`, {})
  },
  async restart(workspaceId) {
    return await API.post(`/api/workspaces/${workspaceId}/restart`, {})
  },
  async stop(workspaceId) {
    return await API.post(`/api/workspaces/${workspaceId}/stop`, {})
  },
  files: {
    async list(workspaceId) {
      return await API.get(`/api/workspaces/${workspaceId}/files`)
    },
    async get(workspaceId, filename) {
      return await API.get(`/api/workspaces/${workspaceId}/files/${filename}`)
    },
    async save(workspaceId, filename, content) {
      return await API.put(`/api/workspaces/${workspaceId}/files/${filename}`, {
        filename,
        content
      })
    },
    async delete(workspaceId, filename) {
      return await API.delete(`/api/workspaces/${workspaceId}/files/${filename}`)
    }
  }
}
```

